const createInfiniteParams = <
  K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>,
>(
  queryKey: QueryKey<Options>,
  page: K,
) => {
  const params = { ...queryKey[0] };
  if (page.body) {
    params.body = {
      ...(queryKey[0].body as any),
      ...(page.body as any),
    };
  }
  if (page.headers) {
    params.headers = {
      ...queryKey[0].headers,
      ...page.headers,
    };
  }
  if (page.path) {
    params.path = {
      ...(queryKey[0].path as any),
      ...(page.path as any),
    };
  }
  if (page.query) {
    params.query = {
      ...(queryKey[0].query as any),
      ...(page.query as any),
    };
  }
  return params as unknown as typeof page;
};

export const listInvestigationAiAnalysisCandidatesInfiniteQueryKey = (
  options: Options<ListInvestigationAiAnalysisCandidatesData>,
): QueryKey<Options<ListInvestigationAiAnalysisCandidatesData>> =>
  createQueryKey('listInvestigationAiAnalysisCandidates', options, true);

/**
 * List Investigation Ai Analysis Candidates
 *
 * The review queue for TAS reasoning output, newest first. Payloads are
 * omitted here; GET /ai-analysis-candidates/{id} returns the full row.
 */
export const listInvestigationAiAnalysisCandidatesInfiniteOptions = (
  options: Options<ListInvestigationAiAnalysisCandidatesData>,
) => {
  const opts = infiniteQueryOptions<
    ListInvestigationAiAnalysisCandidatesResponse,
    ListInvestigationAiAnalysisCandidatesError,
    InfiniteData<ListInvestigationAiAnalysisCandidatesResponse>,
    QueryKey<Options<ListInvestigationAiAnalysisCandidatesData>>,
    | number
    | Pick<
        QueryKey<Options<ListInvestigationAiAnalysisCandidatesData>>[0],
        'body' | 'headers' | 'path' | 'query'
      >
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<ListInvestigationAiAnalysisCandidatesData>>[0],
          'body' | 'headers' | 'path' | 'query'
        > =
          typeof pageParam === 'object'
            ? pageParam
            : {
                query: {
                  offset: pageParam,
                },
              };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await listInvestigationAiAnalysisCandidates({
          ...options,
          ...params,
          signal,
          throwOnError: true,
        });
        return data;
      },
      queryKey: listInvestigationAiAnalysisCandidatesInfiniteQueryKey(options),
    },
  );
  return opts as Omit<typeof opts, 'initialData'>;
};

